/* Compact offline sign database.
 *
 * Binary format (little-endian), generated by tools/build_signs_bin.py:
 *   offset 0:  magic "C2MSDB01" (8 bytes)
 *   offset 8:  u32 sign count
 *   offset 12: records, each 100 bytes:
 *              double lat, double lon, float heading_deg (-999 = unknown),
 *              char type[16], char label[64]  (NUL-padded)
 */
#ifndef SIGNDB_H
#define SIGNDB_H

#include "warner.h"

warner_sign_t *signdb_load(const char *path, int *n_out);
void signdb_free(warner_sign_t *signs);

#endif
